insert into port.catalog_dossiers(id,company_id,ticker,reporting_period_end,source_record_id,reviewed_pages,review_outcome,review_note,gaps,scope_version) values ('a1e0123f-0617-5cec-8638-a88ba982dd10','e1f4c72a-f321-524f-aca8-75881a362efd','TMS','2025-12-31','11ff61ac-fb93-5e00-a185-9eee736a4644','{2,3,4}','reported_assets','Trang 2 gọi ICD Transimex và cảng Mipec là cơ sở hạ tầng thuộc tập đoàn. Trang 4 ghi trở thành công ty mẹ Cảng Mipec vào 11/2022, nhưng không có ngày cụ thể nên để trống hiệu lực. Chưa đủ để coi công ty mẹ trực tiếp khai thác hoặc gắn tỷ lệ vật lý. Kho VSIP II-A được mô tả là dự kiến vận hành 07/2026, không tự đưa thành cảng hoặc tài sản đang khai thác.','["Pháp nhân vận hành và chuỗi vốn ICD/Mipec", "Khớp định danh pháp lý", "Ngày hiệu lực quan hệ và biến động 2026"]','listed-port-candidates-41-report-2025-v1') on conflict do nothing;
