insert into port.catalog_dossiers(id,company_id,ticker,reporting_period_end,source_record_id,reviewed_pages,review_outcome,review_note,gaps,scope_version) values ('6b76c20b-0f68-5a1b-8b3a-c148f669dd02','cc9dfab2-8b85-595c-8dc5-fbc8972a429b','GIC','2025-12-31','0c2b0adf-66da-5245-a71d-ab67d24439c5','{2,3}','no_assertable_assets','Báo cáo ghi đúng tên LOGISTICS, khác lỗi LOGISTCS trong hồ sơ HNX được lập chỉ mục. Trang 2 ghi bãi container đi vào hoạt động tháng 07/2017; trang 3 ghi khai thác bãi và sửa chữa container, không có công ty con/liên kết. Website greenicd.com.vn không tự chứng minh cơ sở được cấp phép là ICD hoặc công ty sở hữu cảng biển.','["Giấy đăng ký doanh nghiệp mới nhất và hồ sơ đổi tên", "Đối chiếu giấy phép trước khi phân loại ICD", "Ngày hiệu lực cụ thể của cơ sở khai thác, không đổi tháng 07/2017 thành ngày đầu tháng"]','listed-port-candidates-41-report-2025-v1') on conflict do nothing;
